import type { Settings } from '../core/types';
import { getSave, saveState } from './storage';
import { STR } from './strings';

const THEME_OPTIONS: Array<{ value: Settings['theme']; label: string }> = [
  { value: 'auto', label: STR.themeAuto },
  { value: 'light', label: STR.themeLight },
  { value: 'dark', label: STR.themeDark },
];

export function openSettings(): void {
  const backdrop = document.createElement('div');
  backdrop.className = 'sheet-backdrop';
  const sheet = document.createElement('div');
  sheet.className = 'sheet';
  sheet.setAttribute('role', 'dialog');
  sheet.setAttribute('aria-label', STR.settings);

  const save = getSave();
  const settings: Settings = { ...save.settings };

  const head = document.createElement('div');
  head.className = 'sheet-head';
  const title = document.createElement('strong');
  title.textContent = STR.settings;
  const close = document.createElement('button');
  close.className = 'sheet-close';
  close.textContent = STR.close;
  close.addEventListener('click', () => remove());
  head.append(title, close);

  // haptics row
  const hapticsRow = document.createElement('div');
  hapticsRow.className = 'sheet-row';
  const hapticsLabel = document.createElement('span');
  hapticsLabel.textContent = STR.haptics;
  const switchBtn = document.createElement('button');
  switchBtn.className = 'switch';
  switchBtn.setAttribute('role', 'switch');
  syncSwitch();
  switchBtn.addEventListener('click', () => {
    settings.haptics = !settings.haptics;
    persist();
    syncSwitch();
  });
  function syncSwitch(): void { switchBtn.setAttribute('aria-checked', String(settings.haptics)); }
  hapticsRow.append(hapticsLabel, switchBtn);

  // appearance row
  const appRow = ...
  const seg = document.createElement('div'); seg.className = 'seg';
  const segBtns = new Map<Settings['theme'], HTMLButtonElement>();
  for (const opt of THEME_OPTIONS) {
    const b = document.createElement('button');
    b.textContent = opt.label;
    b.addEventListener('click', () => { settings.theme = opt.value; persist(); syncSeg(); });
    seg.appendChild(b);
    segBtns.set(opt.value, b);
  }
  function syncSeg(): void { for (const [value, b] of segBtns) b.setAttribute('aria-pressed', String(settings.theme === value)); }
  syncSeg();

  function persist(): void {
    saveState({ ...getSave(), settings: { ...settings } });
    window.dispatchEvent(new CustomEvent('cp:settings-changed'));
  }

  sheet.append(head, hapticsRow, appRow);
  backdrop.appendChild(sheet);
  backdrop.addEventListener('click', (e) => { if (e.target === backdrop) remove(); });
  document.body.appendChild(backdrop);
  function remove(): void { backdrop.remove(); }
}
