{"content":"import { PUZZLES_PER_THEME } from '../core/levels';
import { themeById, THEMES } from '../data/words';
import { getSave } from './storage';
import { navigate } from './router';
import { openSettings } from './settings';
import { STR } from './strings';

function nextUnsolvedIndex(themeId: string, solved: string[]): number {
  let index = 1;
  while (index <= PUZZLES_PER_THEME && solved.includes(`${themeId}:${index}`)) index++;
  return index > PUZZLES_PER_THEME ? 1 : index;
}

export function renderHome(): HTMLElement {
  const root = document.createElement('div');
  root.className = 'home';

  const head = document.createElement('header');
  head.className = 'home-head';
  const h1 = document.createElement('h1');
  h1.textContent = STR.appName;
  const tagline = document.createElement('p');
  tagline.className = 'tagline';
  tagline.textContent = STR.tagline;
  const gear = document.createElement('button');
  gear.className = 'icon-btn';
  gear.setAttribute('aria-label', STR.settings);
  gear.textContent = '⚙';
  gear.addEventListener('click', openSettings);
  head.append(h1, tagline, gear);

  const main = document.createElement('main');
  main.className = 'themes';
  const save = getSave();

  // "Continue" row for the open puzzle, when there is one.
  const progress = save.progress;
  if (progress) {
    const [themeId, idxText] = progress.key.split(':');
    const theme = themeById(themeId);
    if (theme) {
      const index = Number(idxText);
      const row = rowShell(theme.emoji);
      row.classList.add('continue');
      const text = document.createElement('span');
      text.className = 'theme-text';
      const strong = document.createElement('strong');
      strong.textContent = STR.continue;
      const sub = document.createElement('span');
      sub.textContent = STR.continueSub(theme.name, Number.isInteger(index) ? index : 1);
      text.append(strong, sub);
      row.appendChild(text);
      row.addEventListener('click', () => navigate(`#/p/${theme.id}/${index}`));
      main.appendChild(row);
    }
  }

  for (const theme of THEMES) {
    const row = rowShell(theme.emoji);
    const text = document.createElement('span');
    text.className = 'theme-text';
    const strong = document.createElement('strong');
    strong.textContent = theme.name;
    const sub = document.createElement('span');
    const done = save.solved.filter((k) => k.startsWith(`${theme.id}:`)).length;
    sub.textContent = STR.progress(done, PUZZLES_PER_THEME);
    text.append(strong, sub);
    row.appendChild(text);
    if (done >= PUZZLES_PER_THEME) {
      const check = document.createElement('span');
      check.className = 'check';
      check.setAttribute('aria-hidden', 'true');
      check.textContent = '✓';
      row.appendChild(check);
    } else {
      const bar = document.createElement('span');
      bar.className = 'bar';
      const fill = document.createElement('span');
      fill.className = 'bar-fill';
      fill.style.width = `${Math.round((done / PUZZLES_PER_THEME) * 100)}%`;
      bar.appendChild(fill);
      row.appendChild(bar);
    }
    const index = nextUnsolvedIndex(theme.id, save.solved);
    row.addEventListener('click', () => navigate(`#/p/${theme.id}/${index}`));
    main.appendChild(row);
  }

  root.append(head, main);
  return root;
}

/** A full-width 64px row: emoji + (content appended by the caller). */
function rowShell(emoji: string): HTMLButtonElement {
  const row = document.createElement('button');
  row.className = 'theme-row';
  const e = document.createElement('span');
  e.className = 'emoji';
  e.textContent = emoji;
  row.appendChild(e);
  return row;
}
