{"content":"import './style.css';
import '@fontsource/nunito/400.css';
import '@fontsource/nunito/700.css';
import { onRoute } from './ui/router';
import { getSave, loadSave } from './ui/storage';
import { renderHome } from './ui/home';
import { renderPuzzle } from './ui/puzzle';

loadSave();

const metaColor = document.querySelector('meta[name="theme-color"]');
const darkMq = window.matchMedia('(prefers-color-scheme: dark)');

/**
 * Apply the saved appearance preference: 'auto' follows the system
 * prefers-color-scheme, otherwise the chosen value. Sets data-theme on
 * <html> and keeps <meta name="theme-color"> in sync with the --bg token.
 */
function applyTheme(): void {
  const pref = getSave().settings.theme;
  const dark = pref === 'dark' || (pref === 'auto' && darkMq.matches);
  document.documentElement.dataset.theme = dark ? 'dark' : 'light';
  const bg = getComputedStyle(document.documentElement).getPropertyValue('--bg').trim();
  if (bg !== '' && metaColor !== null) metaColor.setAttribute('content', bg);
}

applyTheme();
darkMq.addEventListener('change', applyTheme);
window.addEventListener('cp:settings-changed', applyTheme);

const app = document.getElementById('app')!;
onRoute((route) => {
  const screen = route.name === 'home' ? renderHome() : renderPuzzle(route.themeId, route.index);
  app.replaceChildren(screen);
});
